const body = $json.body ?? $json;
const papers = Array.isArray(body.papers) ? body.papers : [];
if (!papers.length) {
  throw new Error('Request body must include a non-empty papers array.');
}
return [{
  json: {
    papers,
    question: body.question ?? 'What are the key findings?',
    reportName: body.reportName ?? 'Research Analysis Report',
    createdAt: new Date().toISOString(),
  },
}];

