const summaryResult = $('Module 1 - Summarization').first().json;
const gapResponse = $('Module 2 - Gap Detection').first().json;
const gapText = gapResponse.choices?.[0]?.message?.content ?? gapResponse;
let gapData = gapText;
if (typeof gapText === 'string') {
  try {
    gapData = JSON.parse(gapText);
  } catch (error) {
    gapData = { raw: gapText };
  }
}
const papers = summaryResult.summaries ?? summaryResult.data?.summaries ?? summaryResult.items ?? [];
const wordCounts = new Map();
for (const paper of papers) {
  const text = `${paper.title ?? ''} ${paper.summary ?? ''} ${paper.abstract ?? ''}`.toLowerCase();
  for (const word of text.match(/[a-z0-9]{4,}/g) ?? []) {
    wordCounts.set(word, (wordCounts.get(word) ?? 0) + 1);
  }
}
const trends = [...wordCounts.entries()]
  .sort((left, right) => right[1] - left[1])
  .slice(0, 8)
  .map(([term, count]) => ({ term, count }));
return [{
  json: {
    trends,
    topThemes: trends.slice(0, 5),
    loopCount: papers.length,
    gapData,
  },
}];

const summaryResult = $('Module 1 - Summarization').first().json;
const trendResult = $('Module 3 - Trend Detection').first().json;
const papers = summaryResult.summaries ?? [];
const chartData = papers.map((paper, index) => ({
  label: paper.title ?? `Paper ${index + 1}`,
  value: (paper.summary ?? paper.abstract ?? '').length,
}));
return [{
  json: {
    visualizationType: 'bar',
    chartData,
    trendHighlights: trendResult.topThemes ?? [],
    legend: ['Summary Length'],
    note: 'Frontend can render this as a bar or radar chart.',
  },
}];

