const input = $('Prepare Input').first().json;
const summaryResult = $('Module 1 - Summarization').first().json;
const gapResponse = $('Module 2 - Gap Detection').first().json;
const gapText = gapResponse.choices?.[0]?.message?.content ?? gapResponse;
let gapData = gapText;
if (typeof gapText === 'string') {
  try {
    gapData = JSON.parse(gapText);
  } catch (error) {
    gapData = { raw: gapText };
  }
}
const trendResult = $('Module 3 - Trend Detection').first().json;
const visualizationResult = $('Module 4 - Visualization').first().json;
const chatbotResponse = $('Module 5 - Chatbot').first().json;
const chatbotText = chatbotResponse.choices?.[0]?.message?.content ?? chatbotResponse;
let chatbotData = chatbotText;
if (typeof chatbotText === 'string') {
  try {
    chatbotData = JSON.parse(chatbotText);
  } catch (error) {
    chatbotData = { raw: chatbotText };
  }
}
const reportMarkdown = `# ${input.reportName}

## 1. Summarization
${JSON.stringify(summaryResult, null, 2)}

## 2. Gap Detection
${JSON.stringify(gapData, null, 2)}

## 3. Trend Detection
${JSON.stringify(trendResult, null, 2)}

## 4. Visualization
${JSON.stringify(visualizationResult, null, 2)}

## 5. Chatbot
${JSON.stringify(chatbotData, null, 2)}
`;
return [{
  json: {
    id: `rpt_${Date.now()}`,
    createdAt: new Date().toISOString(),
    reportName: input.reportName,
    question: input.question,
    papersCount: input.papers.length,
    analysisReport: {
      summarization: summaryResult,
      gapDetection: gapData,
      trendDetection: trendResult,
      visualization: visualizationResult,
      chatbot: chatbotData,
    },
    reportMarkdown,
  },
}];
